def filter_api_calls(
    logp_with_result: np.ndarray,
    logp_call_only: np.ndarray,
    logp_no_call: np.ndarray,
    tau_filter: float,
) -> tuple[np.ndarray, np.ndarray]:
    """Return an ordered keep mask and one finite margin per proposed call."""
    arrays = [logp_with_result, logp_call_only, logp_no_call]
    for arr in arrays:
        if not isinstance(arr, np.ndarray):
            raise ValueError("Input must be a numpy ndarray")
        if arr.ndim != 2:
            raise ValueError("Input must be a 2D matrix")
        if arr.size == 0:
            raise ValueError("Input must not be empty")
        if not np.isfinite(arr).all():
            raise ValueError("Input contains non-finite values")
        if (arr > 0).any():
            raise ValueError("Input must be nonpositive")
    if not (logp_with_result.shape == logp_call_only.shape == logp_no_call.shape):
        raise ValueError("All input arrays must have the same shape")
    if isinstance(tau_filter, bool):
        raise ValueError("tau_filter must not be a boolean")
    if not np.isfinite(tau_filter):
        raise ValueError("tau_filter must be finite")
    if tau_filter < 0:
        raise ValueError("tau_filter must be nonnegative")
    total_with = logp_with_result.sum(axis=1)
    total_call = logp_call_only.sum(axis=1)
    total_nocall = logp_no_call.sum(axis=1)
    diff_nocall = total_with - total_nocall
    diff_call = total_with - total_call
    keep = (diff_nocall > tau_filter) & (diff_call > tau_filter)
    margin = np.minimum(diff_nocall, diff_call)
    return keep, margin
